INSERT INTO `li_article` VALUES (1347428995495124992, 'admin', '2021-01-08 14:24:41', b'0', 'admin', '2021-10-28 11:44:46', '1347456734864367616', '<p>商家账号及会员账号。</p><p>用户需到前台先注册会员账号才能申请店铺入驻。</p>', 1, '商家账号注册', 'OTHER', b'0');
INSERT INTO `li_article` VALUES (1347429491832283136, 'admin', '2021-01-08 14:26:40', b'0', 'admin', '2021-10-28 11:44:46', '1347456734864367616', '<p>注册商家账号后。</p><p>1.同意店铺入驻协议</p><p>2.填写公司信息。</p><p>3.填写结算账户。</p><p>4.填写店铺基础信息、申请入驻经营的商品类目。</p><p>5.提交审核，平台通过后开店成功。</p>', 2, '商家申请开店', 'OTHER', b'0');
INSERT INTO `li_article` VALUES (1347430272568418304, 'admin', '2021-01-08 14:29:46', b'0', 'admin', '2021-01-08 17:33:01', '1347458431707799552', '<p><span style=\"font-size: 1em;\">可设置店铺的基础信息、退货收件地址、自提点</span></p>', 2, '店铺设置', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347430502135259136, 'admin', '2021-01-08 14:30:40', b'0', 'admin', '2021-10-29 16:25:22', '1347458431707799552', '<p>可设置多个商家客服坐席</p>', 3, '客服设置', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347430608918044672, 'admin', '2021-01-08 14:31:06', b'0', 'admin', '2021-10-29 16:25:17', '1347458431707799552', '<p>点击 设置-物流设置进行 物流设置页面。<br></p><p>可根据不同的地区设置不同的物流模板。</p><p>可选择店铺所支持的物流公司。</p>', 4, '物流设置', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347430851030048768, 'admin', '2021-01-08 14:32:04', b'0', 'admin', '2021-10-14 16:56:36', '1369921726825103362', '<p>1. 设置分组名称、设置排序。</p><p>2.店铺二级商品分类最多可设置二级</p>', 11, '店铺分类维护', 'OTHER', b'0');
INSERT INTO `li_article` VALUES (1347431056441892864, 'admin', '2021-01-08 14:32:53', b'0', 'admin', '2021-05-08 17:28:37', '1369921726825103362', '<p>发布商品</p><p><strong>1、设置商品基础信息</strong>，根据系统提示设置商品名、商品图、价格、库存等，“&nbsp;*&nbsp;” 为必填项。商品图建议尺寸：800*800像素，最多上传5张商品图。<br/></p><p><strong>2、添加商品库存</strong>，如果您上传的商品为多规格的商品，您可以在商品内容中添加新的商品规格。点击添加规格图片，您可以在每个规格中添加图片，买家下单时，可以看到您上传的不同规格的不同图片。划线价：商品没有优惠的情况下，划线价在商品详情会以划线形式显示。<br/></p><p><strong>3、</strong><strong>选择物流信息，</strong>选择商品支持配送方式：快递发货、同城配送、到店自提。<br/></p><p><strong>4、编辑商品详情，</strong>您可以按照商品内容设置商品详情。<br/></p>', 1, '新建／发布商品教程', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347431909718515712, 'admin', '2021-01-08 14:36:16', b'0', 'admin', '2021-05-08 17:32:11', '1369921726825103362', '<p>满减营销<span style=\"font-size: 1em;\">功能支持设置买家购买商品达到一定金额或件数时，可享受包邮、减金额、打折、送积分、送赠品等优惠。</span></p><p>操作路径：电脑端后台 - 营销管理 - 满额管理- 满减/满送/满包邮。</p><p>设置满减的门槛。</p><p>设置满额活动的优惠内容。</p><p>例如：</p><ul><li>支持满X元减现金/打X折 &nbsp; &nbsp;例如：满100元减10元，满100元打8折选其一。</li><li>支持满X元免邮 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 例如：满100全场包邮。</li><li>支持满X元送积分 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 例如：满100元送积分5个。</li><li>支持满X元送优惠 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 例如：满100元送20元优惠券/20元优惠码选其一。</li><li>支持满X元送赠品 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 例如：满100送手机壳一个。</li></ul><p>选择参与活动的商品。</p>', 1, '如果设置满减营销', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347432371884679168, 'admin', '2021-01-08 14:38:06', b'0', 'admin', '2021-01-08 17:11:21', '1369921726825103362', '<p>电脑端后台 - 营销管理 - 拼团管理</p><p><br></p><p><strong>【基础设置】</strong></p><p>1）活动名称：保存后，支持再次修改；</p><p>2）活动时间：</p><p>a、开始时间不得早于当前时间，结束时间不得早于开始时间，不得超过店铺有效期</p><p>b、保存之后，“开始时间”不支持再次修改，“结束时间”可以进行延长，但不能提前</p><p>c、活动时间结束之后，未成团订单将自动关闭并退款，已成团订单仍需及时处理</p><p>&nbsp;</p><p>3）拼团商品：</p><p>a、可选择多个规格商品。</p><p>&nbsp;</p><p>4）拼团价设置：不同的sku可设置不同的拼团价格。</p><p>&nbsp;</p><p>5）拼团有效期：</p><p>a、开团后在有效期内邀请足够好友参团则拼团成功</p><p>b、创建后，买家可在拼团详情页看到有效期倒计时</p><p>&nbsp;</p><p>6）参团人数：开通万人团上限可至10000人，默认3人</p><p><br></p><p>虚拟成团：</p><p>a、拼团达到结束时间未达到要求，使用匿名用户拼团成功。</p>', 2, '拼团管理发布', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347432438783827968, 'admin', '2021-01-08 14:38:22', b'0', 'admin', '2021-05-08 17:33:37', '1369921726825103362', '<p><strong>功能路径</strong><br/>商城电脑端后台 - 营销管理 - 秒杀。<br/></p><p>展示秒杀列表，商家可选择秒杀活动参与活动。</p><p>选择参与活动的SKU，参与时间段，设置秒杀库存。</p>', 3, '秒杀使用教程', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347432646200549376, 'admin', '2021-01-08 14:39:12', b'0', 'admin', '2021-05-08 17:30:33', '1369921726825103362', '<p>您可以在财务对账模块<span style=\"font-size: 1em;\">查看一段时间内您店铺待对账的结算单.</span></p><p>点击明细可以查看这段时间内您店铺每笔订单/退单的收退款记录。<span style=\"font-size: 1em;\"><br/></span></p><p><span style=\"font-size: 1em;\"><br/></span></p>', 1, '如何财务对账', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347432993837047808, 'admin', '2021-01-08 14:40:34', b'0', 'admin', '2021-05-08 17:30:28', '1369921726825103362', '<p>可按照日期筛选结算单列表。</p><p>点击查看结算单详情：展示结算金额、订单/退款/分销流水列表。</p>', 2, '如何查看店铺流水历史', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347434714533486592, 'admin', '2021-01-08 14:47:25', b'0', 'admin', '2021-05-08 17:32:06', '1369921726825103362', '<h3>1. App Clips Experiences</h3><p>App Clips Experiences 是 Session 着重介绍的内容之一，不妨这么理解「体验」：用户通过 NFC 标签、二维码、Message 信息、Map 、Safari、Siri 建议等途径唤起 App Clips 应用程序，在未安装主应用的情况下，体验主应用中的某些服务和功能。<strong>App Clips 可视为为主应用程序导流的又一新途径，不仅仅是在使用过程中给出下载主应用的建议，一旦设备下载安装了主应用程序，之前 App Clips 得到的权限授权以及数据都将一并移入到新下载的主应用中。</strong></p><p>那么如何来唯一标识你开发的 App Clip 提供的不同「体验」呢？答案是 URL 链接。开发者很容易联想到 iOS 9 引入的通用链接（Universal Links）功能，简单罗列对比下异同：</p><ul><li>相同点：两者都可以通过 URL 打开应用程序，代码层面对 URL 的解析、处理逻辑和流程相似；</li><li>不同点：App Clip 体验 URL 必须在 App Store Connect 进行注册，更多详细配置点击&nbsp;<a href=\"https://xiaozhuanlan.com/topic/4063519872\" target=\"_blank\">Configure and Link Your App Clips</a>&nbsp;一文；通用链接则是需要先在开发者中心开启 Associated Domains 选项，接着在工程配置中 Associated Domains 一栏填入你想支持的域名，最后一步是将支持的 URL 以 JSON 格式写入到 apple-app-site-association 文件中，放到域名服务器下的&nbsp;<code>.well-known</code>&nbsp;子文件夹中，注意服务器必须支持 HTTPS。</li></ul><p>了解了 URL 唯一标识 App Clip 提供的体验服务，有哪些途径用于唤醒 App Clip 呢？</p><ol><li>NFC ，关于 NFC 的知识点，<a href=\"https://hacpai.com/article/1365949196429\" target=\"_blank\">引用大佬的解释</a>：「简单的说，就是一个标签，内部含电子元件，可以记录一些信息，通常1KB左右存储容量的就能满足常用需要。而当你用手机接近（开启NFC）标签时，NFC会自动扫描标签内所含有的信息，然后在手机上面显示标签信息或者执行标签所包含的命令。使用NFC可以提供一些便利，如到家时，你想连接家里的WiFI，然后登陆QQ等，你可以自己制作一个这样的标签，然后贴在家门口处，回家一打开门，用手机一扫描此标签，手机会自动执行上述命令。当然，你也可以发挥自己的想象力，如给手机上面安装远程开机功能，然后制作成这样的标签，回家一扫描，电脑自动打开，当然还有更多的创意，只要你能想得到」</li><li>QR codes，熟知的二维码；</li><li>Maps</li><li>Siri 建议</li><li>Safari，同通用链接类似，需要修改 apple-app-site-association 配置文件，加入对 App Clip 的支持，这样当你打开某个注册过的链接时，顶部就会呈现用于唤起 App Clip 的横幅 UI</li><li>Message 应用中识别 App Clip 体验链接，然后以卡片形式呈现。</li></ol><p>苹果将于年底推出 App Clip codes，结合了 NFC 的易用性，同时可视化图形展示，可以通过轻碰和扫描来快速识别。</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/d2e564e9a2692e0ecca01b004a8bce65.png\" alt=\"\"/></p>', 1, '一笔订单可以使用多张优惠券吗？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347434895337349120, 'admin', '2021-01-08 14:48:08', b'0', 'admin', '2021-05-08 17:33:42', '1369921726825103362', '<p>一张优惠券不支持核销多次，只能核销一次。<br/></p>', 4, '一张优惠券可以核销多次吗？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347435331821789184, 'admin', '2021-01-08 14:49:52', b'0', 'admin', '2021-10-28 11:45:04', '1347450411015757824', '<p>已经发放到客户账号里面的优惠券可以作废，停止用户用券，但是不支持回收。</p><p>停止用券的操作路径：微商城电脑端后台 - 应用 - 营销玩法 - 优惠券 - 点击【已领取】的数量 - 进入已领取的客户列表 - 点击【停止用户用券】。</p>', 5, '如何停用发放给客户的优惠券？', 'OTHER', b'0');
INSERT INTO `li_article` VALUES (1347435630384930816, 'admin', '2021-01-08 14:51:03', b'0', 'admin', '2021-10-28 11:45:04', '1347450411015757824', '<p>优惠券不能用来抵扣订单中的运费。<br></p>', 6, '优惠券可以抵扣运费吗？', 'OTHER', b'0');
INSERT INTO `li_article` VALUES (1347435809779507200, 'admin', '2021-01-08 14:51:46', b'0', 'admin', '2021-05-08 17:34:24', '1369921726825103362', '<p>可以使用优惠券</p>', 7, '多人拼团订单可以使用优惠券吗？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347435999282356224, 'admin', '2021-01-08 14:52:31', b'0', 'admin', '2021-12-01 21:19:39', '1347450411015757824', '<p>优惠券只能在自己店铺使用，不能实现多店通用。</p>', 8, '优惠券可以多个店铺通用吗？', 'OTHER', b'0');
INSERT INTO `li_article` VALUES (1347439387113971712, 'admin', '2021-01-08 15:05:59', b'0', 'admin', '2021-05-08 17:29:02', '1369921726825103362', '<p>给商品创建分组后，店铺主页可以按照商品分组进行展示不同类目的商品。<br/></p>', 5, '添加商品分组，有什么作用？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347439575983480832, 'admin', '2021-01-08 15:06:44', b'0', 'admin', '2021-05-08 17:29:21', '1369921726825103362', '<p>可以上传5张，超过就无法上传了<br/></p>', 6, '商品主图可以上传多少张？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347439915625635840, 'admin', '2021-01-08 15:08:05', b'0', 'admin', '2021-05-08 17:28:30', '1369921726825103362', '<p>可上架后最晚十分钟可以展示。<br/></p>', 7, '商品上架后，多久会显示？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347440117820448768, 'admin', '2021-01-08 15:08:53', b'0', 'admin', '2021-11-09 10:41:21', '1369921726825103362', '<p>库存最大值不能超过10000000件，建议您根据实际库存进行设置。<br/></p>', 8, '商品库存有数量限制吗？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347440480636133376, 'admin', '2021-01-08 15:10:19', b'0', 'admin', '2021-12-01 21:19:38', '1369921726825103362', '<p>目前商品类型分为实物商品、虚拟商品。</p><p>实物商品与虚拟商品的区别：</p><p>实物商品：需实物进行发货。</p><p>虚拟商品：不需要快递，购买后获取验证码。</p>', 9, '商品类型有哪些？', 'OTHER', b'0');
INSERT INTO `li_article` VALUES (1347441567598403584, 'admin', '2021-01-08 15:14:39', b'0', 'admin', '2021-12-01 21:19:37', '1369921726825103362', '<p>商品编辑里面的规格名、规格值历史记录目前不支持删除。<br/></p>', 10, '商品编辑里面的规格名、规格值历史记录可以删除吗？', 'OTHER', b'0');
INSERT INTO `li_article` VALUES (1347441948684476416, 'admin', '2021-01-08 15:16:09', b'0', 'admin', '2021-05-08 17:28:55', '1369921726825103362', '<p>一个商品可以添加3个主规格，每个主规格可以添加200个子规格（注：子规格总字数需在5000字以下）。</p><p>超过600个的情况下建议发布成多个商品。</p>', 3, '一个商品可以添加多少规格？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347444467808624640, 'admin', '2021-01-08 15:26:10', b'0', 'admin', '2021-05-08 17:28:43', '1369921726825103362', '<p>商品销量不会减少哦。商品销量是历史已发生的，不会因为删除规格而改变。<br/></p>', 4, '商品如果删除其中一个规格，商品详情中展示的总销量会减少吗？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347445328169426944, 'admin', '2021-01-08 15:29:35', b'0', 'admin', '2021-08-17 11:30:51', '1369921726825103362', '<p>多人拼团有虚拟成团的功能。</p><p>在新建多人拼团活动的时候，如果想要提高成团率，可以展开高级设置，勾选模拟成团。如果不希望买家虚拟成团，则可以不勾选虚拟成团。<br/>开启模拟成团后，满足条件的团，系统将会模拟“匿名买家”凑满该团，仅需对真实拼团买家发货。建议合理开启，以提高成团率。</p>', 18, '多人拼团有虚拟成团的功能吗？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347445482180075520, 'admin', '2021-01-08 15:30:12', b'0', 'admin', '2021-10-02 12:23:56', '1369921726825103362', '<p>已成团订单其中1笔申请退款，按正常订单处理，这个团的其他订单不受影响，还是可以正常发货的。<br/></p>', 19, '已成团订单，其中有一人申请退款，对同团其他订单有影响吗？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347445690712481792, 'admin', '2021-01-08 15:31:02', b'0', 'admin', '2021-05-08 17:32:29', '1369921726825103362', '<p>123</p>', 1, '多人拼团活动结束后，还未成团的订单会怎么样？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347445984301178880, 'admin', '2021-01-08 15:32:12', b'0', 'admin', '2021-10-28 11:45:05', '1347450411015757824', '<h3>1. App Clips Experiences</h3><p>App Clips Experiences 是 Session 着重介绍的内容之一，不妨这么理解「体验」：用户通过 NFC 标签、二维码、Message 信息、Map 、Safari、Siri 建议等途径唤起 App Clips 应用程序，在未安装主应用的情况下，体验主应用中的某些服务和功能。<strong>App Clips 可视为为主应用程序导流的又一新途径，不仅仅是在使用过程中给出下载主应用的建议，一旦设备下载安装了主应用程序，之前 App Clips 得到的权限授权以及数据都将一并移入到新下载的主应用中。</strong></p><p>那么如何来唯一标识你开发的 App Clip 提供的不同「体验」呢？答案是 URL 链接。开发者很容易联想到 iOS 9 引入的通用链接（Universal Links）功能，简单罗列对比下异同：</p><ul><li>相同点：两者都可以通过 URL 打开应用程序，代码层面对 URL 的解析、处理逻辑和流程相似；</li><li>不同点：App Clip 体验 URL 必须在 App Store Connect 进行注册，更多详细配置点击 <a href=\"https://xiaozhuanlan.com/topic/4063519872\" target=\"_blank\">Configure and Link Your App Clips</a> 一文；通用链接则是需要先在开发者中心开启 Associated Domains 选项，接着在工程配置中 Associated Domains 一栏填入你想支持的域名，最后一步是将支持的 URL 以 JSON 格式写入到 apple-app-site-association 文件中，放到域名服务器下的 <code>.well-known</code> 子文件夹中，注意服务器必须支持 HTTPS。</li></ul><p>了解了 URL 唯一标识 App Clip 提供的体验服务，有哪些途径用于唤醒 App Clip 呢？</p><ol><li>NFC ，关于 NFC 的知识点，<a href=\"https://hacpai.com/article/1365949196429\" target=\"_blank\">引用大佬的解释</a>：「简单的说，就是一个标签，内部含电子元件，可以记录一些信息，通常1KB左右存储容量的就能满足常用需要。而当你用手机接近（开启NFC）标签时，NFC会自动扫描标签内所含有的信息，然后在手机上面显示标签信息或者执行标签所包含的命令。使用NFC可以提供一些便利，如到家时，你想连接家里的WiFI，然后登陆QQ等，你可以自己制作一个这样的标签，然后贴在家门口处，回家一打开门，用手机一扫描此标签，手机会自动执行上述命令。当然，你也可以发挥自己的想象力，如给手机上面安装远程开机功能，然后制作成这样的标签，回家一扫描，电脑自动打开，当然还有更多的创意，只要你能想得到」</li><li>QR codes，熟知的二维码；</li><li>Maps</li><li>Siri 建议</li><li>Safari，同通用链接类似，需要修改 apple-app-site-association 配置文件，加入对 App Clip 的支持，这样当你打开某个注册过的链接时，顶部就会呈现用于唤起 App Clip 的横幅 UI</li><li>Message 应用中识别 App Clip 体验链接，然后以卡片形式呈现。</li></ol><p>苹果将于年底推出 App Clip codes，结合了 NFC 的易用性，同时可视化图形展示，可以通过轻碰和扫描来快速识别。</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/d2e564e9a2692e0ecca01b004a8bce65.png\" alt=\"\"></p>', 1, '如何取消多人拼团订单？', 'OTHER', b'0');
INSERT INTO `li_article` VALUES (1347449374255112192, 'admin', '2021-01-08 15:45:40', b'0', 'admin', '2021-10-28 11:45:05', '1347450411015757824', '<p>App Clips 是今年 WWDC20 大会的亮点之一，罗列几个开发者感兴趣的问题：什么是 App Clips；实际应用场景中是如何交互的；构建 App Clips 的有哪些前置条件；如何在已有项目中添加对 App Clips 的支持等一系列问题。</p><p>在回答上述几个问题之前，我们先来明确三个概念：1. App，即我们开发的应用程序，提供完整服务功能，亦称之为主应用；2. App Clip Experience，本质是一个 URL 链接，唯一标识某项体验服务，e.g. 餐饮类应用程序中的点餐服务、预定餐桌服务、付款操作等；3. App Clip，能够让用户在未安装你发布的完整应用程序情况下，就能体验其中的部分功能，session 中开篇就提到 “App Clips are an additive feature.” ，即附加功能，这意味着你必须先拥有一个 App 主应用程序，才能继续开发该应用的 App Clip，更多关于 App 主应用程序和 App Clip 的关联关系此处先按下不表，下文展开，此外 App Clips 不难让人联想到 Android Instant apps 、微信小程序以及 PWA，三者的横向比较推荐一波卓同学的<a href=\"https://juejin.im/post/5ef41c9b6fb9a07e6143b0d0\" target=\"_blank\">苹果 App Clip 技术详解一文</a>。</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/424e3a484ff1d6ea9bc30f71d673fa6c.png\" alt=\"\"></p><h3>1. App Clips Experiences</h3><p>App Clips Experiences 是 Session 着重介绍的内容之一，不妨这么理解「体验」：用户通过 NFC 标签、二维码、Message 信息、Map 、Safari、Siri 建议等途径唤起 App Clips 应用程序，在未安装主应用的情况下，体验主应用中的某些服务和功能。<strong>App Clips 可视为为主应用程序导流的又一新途径，不仅仅是在使用过程中给出下载主应用的建议，一旦设备下载安装了主应用程序，之前 App Clips 得到的权限授权以及数据都将一并移入到新下载的主应用中。</strong></p><p>那么如何来唯一标识你开发的 App Clip 提供的不同「体验」呢？答案是 URL 链接。开发者很容易联想到 iOS 9 引入的通用链接（Universal Links）功能，简单罗列对比下异同：</p><ul><li>相同点：两者都可以通过 URL 打开应用程序，代码层面对 URL 的解析、处理逻辑和流程相似；</li><li>不同点：App Clip 体验 URL 必须在 App Store Connect 进行注册，更多详细配置点击 <a href=\"https://xiaozhuanlan.com/topic/4063519872\" target=\"_blank\">Configure and Link Your App Clips</a> 一文；通用链接则是需要先在开发者中心开启 Associated Domains 选项，接着在工程配置中 Associated Domains 一栏填入你想支持的域名，最后一步是将支持的 URL 以 JSON 格式写入到 apple-app-site-association 文件中，放到域名服务器下的 <code>.well-known</code> 子文件夹中，注意服务器必须支持 HTTPS。</li></ul><p>了解了 URL 唯一标识 App Clip 提供的体验服务，有哪些途径用于唤醒 App Clip 呢？</p><ol><li>NFC ，关于 NFC 的知识点，<a href=\"https://hacpai.com/article/1365949196429\" target=\"_blank\">引用大佬的解释</a>：「简单的说，就是一个标签，内部含电子元件，可以记录一些信息，通常1KB左右存储容量的就能满足常用需要。而当你用手机接近（开启NFC）标签时，NFC会自动扫描标签内所含有的信息，然后在手机上面显示标签信息或者执行标签所包含的命令。使用NFC可以提供一些便利，如到家时，你想连接家里的WiFI，然后登陆QQ等，你可以自己制作一个这样的标签，然后贴在家门口处，回家一打开门，用手机一扫描此标签，手机会自动执行上述命令。当然，你也可以发挥自己的想象力，如给手机上面安装远程开机功能，然后制作成这样的标签，回家一扫描，电脑自动打开，当然还有更多的创意，只要你能想得到」</li><li>QR codes，熟知的二维码；</li><li>Maps</li><li>Siri 建议</li><li>Safari，同通用链接类似，需要修改 apple-app-site-association 配置文件，加入对 App Clip 的支持，这样当你打开某个注册过的链接时，顶部就会呈现用于唤起 App Clip 的横幅 UI</li><li>Message 应用中识别 App Clip 体验链接，然后以卡片形式呈现。</li></ol><p>苹果将于年底推出 App Clip codes，结合了 NFC 的易用性，同时可视化图形展示，可以通过轻碰和扫描来快速识别。</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/d2e564e9a2692e0ecca01b004a8bce65.png\" alt=\"\"></p><h3>2. App Clips</h3><p>App Clips 发布之时，想必部分 iOSer 当时第一反应就是<strong>“完了，又要适配新功能拉“</strong>。实际上为已有项目添加对 App Clip 的支持非常简单，就是新增一个 App Clip 应用程序的 target，请确保你已经安装了 Xcode12 beta 版本，那么在 <code>New => Target</code> 弹出的面板中会发现多了 App Clip 选项：</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/72d5e03f4575f8bee94a5a4dbfebeef3.png\" alt=\"\"></p><p>关于 App Clip，我们需要明确如下四点：</p><ol><li>App Clip 是第一个独立的应用程序，包含了必要的功能代码和资源文件，专门负责处理「体验」服务请求；</li><li>App Clip 必须关联一个主应用程序，需要在 App Store Connect 中创建一个版本，和主应用一起提交审核，session 中提及 <em>”You cannot upload an App Clip or its app independently of one another“</em>，这么看来两者都不能单独提审；</li><li>主应用程序和其关联的 App Clip 提交到 App Store 之后，两者就被分开存储，独立存在。假设用户通过上面某种途径打开「体验」链接，设备上没有安装主应用程序，那么系统就会下载 App Clip 到设备上，接着会被唤起调用；否则主应用程序总是第一选择，实际上用户一旦安装了主应用程序，系统就会移除掉 App Clip，因此请牢记一点：<strong>主应用程序也必须有处理 App Clip 体验链接的代码，否则一旦用户安装了主应用程序（此时 App Clip 会被系统移除），再识别体验链接时就会跳转至主应用程序进行处理，此时若未相关处理，就只是打开应用程序而已了；</strong></li><li>App Clip 包大小限制在 10 MB，满足基本功能前提下包体积越小越好，某些资源文件的下载可适当延后，另外技术群里也提到 App Clip 是否可以作为一个壳，内容呈现是基于 WKWebview 展示，目前存疑；</li></ol><p>关于 App Clip 的注意事项就是上述几点，那么我们如何基于主应用程序来开发和构建 App Clip 呢？通常市面上大部分应用程序都是基于 Tab Bar 控制器来划分功能模块，如下提供了四个功能模块：</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/13d541fc5a77ab0e8f9470f1670b8fea.png\" alt=\"\"></p><p>现在开始设计 App Clip 所需的功能，我们仅保留对外提供服务的代码和资源，去除类似用户信息面板等不必要的功能模块。</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/50682b3df946de0d45c70785c8a6ab90.png\" alt=\"\"></p><p>显然 App Clip 旨在提供「体验」服务，我们希望唤起 App Clip 后，让用户快速到达目标功能，因此 Tab Bar 结构并不适用，调整如下：</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/5d265abc0367878f750545bce3b16db9.png\" alt=\"\"></p><p>App Clips 负责处理体验链接，建议单次处理一个体验链接请求。</p><h3>3. Xcode 上手</h3><p>苹果官方提供了一个名为 Fruta 的 Demo ，用于演示如何在已有项目中新增对 App Clip 的支持，Demo 下载地址<a href=\"https://docs-assets.developer.apple.com/published/b7ada4cd51/FrutaBuildingAFeatureRichAppWithSwiftUI.zip\" target=\"_blank\">传送门</a>。</p><p>上文说到已有项目添加对 App Clip 的支持非常简单，就是新增一个 App Clip 应用程序的 target。</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/20529ac1d6f74ee63ede45405f8fd14b.png\" alt=\"\"></p><p>选中 App Clip 新建一个 target，填写必要信息即可。</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/2d6e07e301de628ac8bc762b2426bc2d.png\" alt=\"\"></p><p>由于主应用程序(iOS or macOS)和 App Clip 某些资源文件是共用的，因此我们可以新建一个共享的 Asset Catalog ，<strong>此处注意勾选需要共享的几个 target</strong>。</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/40aa8627ed61dc595d552bfb2c7a37a0.png\" alt=\"\"></p><p>接着将共用的资源文件都放入到新建的 Asset 文件夹下：</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/0f2b161973a64341cb1547abd6c008a3.png\" alt=\"\"></p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/c33b8d6455b2ff50d7f9a3c91ac116e7.png\" alt=\"\"></p><p>接着我们要为 App Clip Target 按需「添加」主应用中已经实现的类、文件或是整个模块，对于文件来说，只需要在 Target Membership 中勾选上 Clip target 即可。</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/17ae9337f84fac2a46ba7c5df7a6bc68.png\" alt=\"\"></p><p>这里涉及到共用代码不同平台的区分处理问题，因此我们需要为 Clip target 的 Debug 和 Release 配置项中添加一个 APPCLIP 宏，如下所示：</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/9dc3cb402d4ad499f835f33bf38c4e41.png\" alt=\"\"></p><p>相应地，我们需要在代码中使用宏条件进行分支处理：</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/e56d3e9c38627f29bb23a9ba26ab99db.png\" alt=\"\"></p><p>此处可能有读者要问了，上文说到通用链接的处理和 App Clip 体验链接的处理两者类似，是如何解析链接处理请求呢？官方提供的 Demo 中 <code>FrutaApp.swift</code> 整个文件被 iOS 主应用程序和 App Clip 共享，免不了内部用 <code>APPCLIP</code> 宏来做分支处理，注意下面的 <code>handleUserActivity</code> 方法就是用来处理体验链接。</p><p>```swift<br>import SwiftUI</p><p><br></p>', 1, '一个商品只能参加一个拼团活动吗？', 'OTHER', b'0');
INSERT INTO `li_article` VALUES (1347449767181705216, 'admin', '2021-01-08 15:47:14', b'0', 'admin', '2021-10-28 11:45:07', '1347450411015757824', '<p>App Clips 是今年 WWDC20 大会的亮点之一，罗列几个开发者感兴趣的问题：什么是 App Clips；实际应用场景中是如何交互的；构建 App Clips 的有哪些前置条件；如何在已有项目中添加对 App Clips 的支持等一系列问题。</p><p>在回答上述几个问题之前，我们先来明确三个概念：1. App，即我们开发的应用程序，提供完整服务功能，亦称之为主应用；2. App Clip Experience，本质是一个 URL 链接，唯一标识某项体验服务，e.g. 餐饮类应用程序中的点餐服务、预定餐桌服务、付款操作等；3. App Clip，能够让用户在未安装你发布的完整应用程序情况下，就能体验其中的部分功能，session 中开篇就提到 “App Clips are an additive feature.” ，即附加功能，这意味着你必须先拥有一个 App 主应用程序，才能继续开发该应用的 App Clip，更多关于 App 主应用程序和 App Clip 的关联关系此处先按下不表，下文展开，此外 App Clips 不难让人联想到 Android Instant apps 、微信小程序以及 PWA，三者的横向比较推荐一波卓同学的<a href=\"https://juejin.im/post/5ef41c9b6fb9a07e6143b0d0\" target=\"_blank\">苹果 App Clip 技术详解一文</a>。</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/424e3a484ff1d6ea9bc30f71d673fa6c.png\" alt=\"\"></p><h3>1. App Clips Experiences</h3><p>App Clips Experiences 是 Session 着重介绍的内容之一，不妨这么理解「体验」：用户通过 NFC 标签、二维码、Message 信息、Map 、Safari、Siri 建议等途径唤起 App Clips 应用程序，在未安装主应用的情况下，体验主应用中的某些服务和功能。<strong>App Clips 可视为为主应用程序导流的又一新途径，不仅仅是在使用过程中给出下载主应用的建议，一旦设备下载安装了主应用程序，之前 App Clips 得到的权限授权以及数据都将一并移入到新下载的主应用中。</strong></p><p>那么如何来唯一标识你开发的 App Clip 提供的不同「体验」呢？答案是 URL 链接。开发者很容易联想到 iOS 9 引入的通用链接（Universal Links）功能，简单罗列对比下异同：</p><ul><li>相同点：两者都可以通过 URL 打开应用程序，代码层面对 URL 的解析、处理逻辑和流程相似；</li><li>不同点：App Clip 体验 URL 必须在 App Store Connect 进行注册，更多详细配置点击 <a href=\"https://xiaozhuanlan.com/topic/4063519872\" target=\"_blank\">Configure and Link Your App Clips</a> 一文；通用链接则是需要先在开发者中心开启 Associated Domains 选项，接着在工程配置中 Associated Domains 一栏填入你想支持的域名，最后一步是将支持的 URL 以 JSON 格式写入到 apple-app-site-association 文件中，放到域名服务器下的 <code>.well-known</code> 子文件夹中，注意服务器必须支持 HTTPS。</li></ul><p>了解了 URL 唯一标识 App Clip 提供的体验服务，有哪些途径用于唤醒 App Clip 呢？</p><ol><li>NFC ，关于 NFC 的知识点，<a href=\"https://hacpai.com/article/1365949196429\" target=\"_blank\">引用大佬的解释</a>：「简单的说，就是一个标签，内部含电子元件，可以记录一些信息，通常1KB左右存储容量的就能满足常用需要。而当你用手机接近（开启NFC）标签时，NFC会自动扫描标签内所含有的信息，然后在手机上面显示标签信息或者执行标签所包含的命令。使用NFC可以提供一些便利，如到家时，你想连接家里的WiFI，然后登陆QQ等，你可以自己制作一个这样的标签，然后贴在家门口处，回家一打开门，用手机一扫描此标签，手机会自动执行上述命令。当然，你也可以发挥自己的想象力，如给手机上面安装远程开机功能，然后制作成这样的标签，回家一扫描，电脑自动打开，当然还有更多的创意，只要你能想得到」</li><li>QR codes，熟知的二维码；</li><li>Maps</li><li>Siri 建议</li><li>Safari，同通用链接类似，需要修改 apple-app-site-association 配置文件，加入对 App Clip 的支持，这样当你打开某个注册过的链接时，顶部就会呈现用于唤起 App Clip 的横幅 UI</li><li>Message 应用中识别 App Clip 体验链接，然后以卡片形式呈现。</li></ol><p>苹果将于年底推出 App Clip codes，结合了 NFC 的易用性，同时可视化图形展示，可以通过轻碰和扫描来快速识别。</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/d2e564e9a2692e0ecca01b004a8bce65.png\" alt=\"\"></p><h3>2. App Clips</h3><p>App Clips 发布之时，想必部分 iOSer 当时第一反应就是<strong>“完了，又要适配新功能拉“</strong>。实际上为已有项目添加对 App Clip 的支持非常简单，就是新增一个 App Clip 应用程序的 target，请确保你已经安装了 Xcode12 beta 版本，那么在 <code>New => Target</code> 弹出的面板中会发现多了 App Clip 选项：</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/72d5e03f4575f8bee94a5a4dbfebeef3.png\" alt=\"\"></p><p>关于 App Clip，我们需要明确如下四点：</p><ol><li>App Clip 是第一个独立的应用程序，包含了必要的功能代码和资源文件，专门负责处理「体验」服务请求；</li><li>App Clip 必须关联一个主应用程序，需要在 App Store Connect 中创建一个版本，和主应用一起提交审核，session 中提及 <em>”You cannot upload an App Clip or its app independently of one another“</em>，这么看来两者都不能单独提审；</li><li>主应用程序和其关联的 App Clip 提交到 App Store 之后，两者就被分开存储，独立存在。假设用户通过上面某种途径打开「体验」链接，设备上没有安装主应用程序，那么系统就会下载 App Clip 到设备上，接着会被唤起调用；否则主应用程序总是第一选择，实际上用户一旦安装了主应用程序，系统就会移除掉 App Clip，因此请牢记一点：<strong>主应用程序也必须有处理 App Clip 体验链接的代码，否则一旦用户安装了主应用程序（此时 App Clip 会被系统移除），再识别体验链接时就会跳转至主应用程序进行处理，此时若未相关处理，就只是打开应用程序而已了；</strong></li><li>App Clip 包大小限制在 10 MB，满足基本功能前提下包体积越小越好，某些资源文件的下载可适当延后，另外技术群里也提到 App Clip 是否可以作为一个壳，内容呈现是基于 WKWebview 展示，目前存疑；</li></ol><p>关于 App Clip 的注意事项就是上述几点，那么我们如何基于主应用程序来开发和构建 App Clip 呢？通常市面上大部分应用程序都是基于 Tab Bar 控制器来划分功能模块，如下提供了四个功能模块：</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/13d541fc5a77ab0e8f9470f1670b8fea.png\" alt=\"\"></p><p>现在开始设计 App Clip 所需的功能，我们仅保留对外提供服务的代码和资源，去除类似用户信息面板等不必要的功能模块。</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/50682b3df946de0d45c70785c8a6ab90.png\" alt=\"\"></p><p>显然 App Clip 旨在提供「体验」服务，我们希望唤起 App Clip 后，让用户快速到达目标功能，因此 Tab Bar 结构并不适用，调整如下：</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/5d265abc0367878f750545bce3b16db9.png\" alt=\"\"></p><p>App Clips 负责处理体验链接，建议单次处理一个体验链接请求。</p><h3>3. Xcode 上手</h3><p>苹果官方提供了一个名为 Fruta 的 Demo ，用于演示如何在已有项目中新增对 App Clip 的支持，Demo 下载地址<a href=\"https://docs-assets.developer.apple.com/published/b7ada4cd51/FrutaBuildingAFeatureRichAppWithSwiftUI.zip\" target=\"_blank\">传送门</a>。</p><p>上文说到已有项目添加对 App Clip 的支持非常简单，就是新增一个 App Clip 应用程序的 target。</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/20529ac1d6f74ee63ede45405f8fd14b.png\" alt=\"\"></p><p>选中 App Clip 新建一个 target，填写必要信息即可。</p><p><img src=\"https://images.xiaozhuanlan.com/photo/2020/2d6e07e301de628ac8bc762b2426bc2d.png\" alt=\"\"></p><p>由于主应用程序(iOS or macOS)和 App Clip 某些资源文件是共用的，因此我们可以新建一个共享的 Asset Catalog ，<strong>此处注意勾选需要共享的几个 target</strong>。</p>', 1, '拼团商品可以选择自提吗？', 'OTHER', b'0');
INSERT INTO `li_article` VALUES (1347450051882672128, 'admin', '2021-01-08 15:48:21', b'0', 'admin', '2021-06-07 11:46:16', '1369921726825103362', '<p>阿迪散发的撒发</p><p>sad发生地方</p>', 1, '虚拟商品可以参加多人拼团吗？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347455276571975680, 'admin', '2021-01-08 16:09:07', b'0', 'admin', '2021-05-08 17:28:49', '1369921726825103362', '<p>设置商品规格后，要在[商品库存]区域分别去单独设置不同规格的价格、库存等信息。</p><p>商品可以添加3个主规格，每个主规格可以添加200个子规格（在该子规格总字数不超过5000个字的情况下）。</p><p>商品名称您可以手动输入，例如颜色、款式。注意：输入具体规格参数时，点击【回车键】即可键入。<br/></p><p>在规格名中您可以填写规格值，例如衣服、鞋子尺码。在一个商品中，支持设置多个规格名和规格值。<br/></p><p>您可以设置多个商品规格，但是商品规格为包含关系，即买家需要全选您设置的规格，例如您设置了3个规格名，买家需要选择全部三个规格才可以下单，不然无法下单。因此建议您仅设置一个规格名，多个规格值哦。<br/></p><p>勾选添加规格图片，您可以在您的每一个分规格中添加图片。仅支持为第一组规格设置规格图片（最多40张图），买家选择不同规格会看到对应规格图片，建议尺寸：800 x 800像素</p><p>如果您需要删除商品规格请您编辑商品选择商品规格，点击右侧×图标即可。</p>', 2, '商品规格设置教程', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347460085660278784, 'admin', '2021-01-08 16:28:14', b'0', 'admin', '2021-12-01 09:50:10', '1369921726825103362', '<p><b>直接在商品管理页面，鼠标悬放至对应商品，修改商品库存。<br/></b></p><p><b>不同的规格可设置不同的库存数量</b></p>', 12, '怎么修改商品库存？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347466553893609472, 'admin', '2021-01-08 16:53:56', b'0', 'admin', '2021-05-08 17:29:57', '1369921726825103362', '<p>操作路径：商城电脑端后台 - 订单 - 交易列表 - 查看详情 - 收货人信息 - 修改。<br/></p><p>1.只有待付款或待发货的订单支持修改</p><p>2.只有配送方式是快递发货的订单支持修改<br/></p>', 1, '如何修改订单收货地址？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347467444453400576, 'admin', '2021-01-08 16:57:28', b'0', 'admin', '2021-05-08 17:30:02', '1369921726825103362', '<p>订单发货操作路径：电脑端后台 - 订单 - 订单查询，找到待发货的订单并点击发货。<br/></p><p>选择快递公司并填写运单号。</p>', 1, '如何订单发货', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347471480271429632, 'admin', '2021-01-08 17:13:30', b'0', 'admin', '2021-12-01 21:19:36', '1347450411015757824', '<p>一个秒杀活动只能参与一次，不能重复提交参加。<br></p>', 10, '一个秒杀活动能参与多次吗？', 'OTHER', b'0');
INSERT INTO `li_article` VALUES (1347476270544084992, 'admin', '2021-01-08 17:32:32', b'0', NULL, NULL, '1347458431707799552', '<p>店铺首页分为：移动端、PC端。</p><p>店铺可以有多个首页，可选择其中一个进行发布。</p><p>页面设置中，商家可拖拽各种模块进行装修。</p>', 1, '如果发布店铺首页', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347488132622999552, 'admin', '2021-01-08 18:19:41', b'0', 'admin', '2021-05-08 17:30:19', '1369921726825103362', '<p>订单金额为：周期内的付款订单。</p><p>退款金额为：周期内的退款金额。</p><p>佣金金额为：周期内订单平台收取的佣金。</p><p>商品分销金额：周期内订单产生的分销佣金。</p><p>平台优惠券金额：周期内订单使用的平台优惠券平台承担部分的金额。</p><p>退还佣金：退款订单平台收取的佣金。</p><p>退还平台优惠券：退款订单商家收取的平台优惠券金额。</p><p><br/></p><p>结算金额=订单金额-平台分佣-退单金额-商品分销费用-退还平台优惠券+退还佣金+平台优惠券+积分抵现金额。</p><p><br/></p><p>商品分销费用不进行退还。</p>', 4, '结算规则', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347488451167805440, 'admin', '2021-01-08 18:20:57', b'0', 'admin', '2021-11-25 23:09:07', '1369921726825103362', '<p>目前平台支持开具增值税普通发票。</p><p>发票管理只展示用户提交的发票信息，不进行实际发票开具操作。</p>', 3, '商家开具发票', 'OTHER', b'0');
INSERT INTO `li_article` VALUES (1347731598330322944, 'admin', '2021-01-09 10:27:07', b'0', 'admin', '2021-08-03 01:51:15', '1347730780659146752', '<p>用户前台创建订单。订单状态为：待付款。</p><p>点击 订单-订单列表-详情-确定收款，进行收款。</p><p>后台确定收款的订单，退款时需填写收款银行信息。hhhh</p>', 1, '平台如何在后台收款？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347732213374672896, 'admin', '2021-01-09 10:29:34', b'0', NULL, NULL, '1347732008847826944', '<p>同一时间只能发布一个秒杀活动。</p>', 1, '同一时间可以发布多个秒杀活动吗？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1347733073714503680, 'admin', '2021-01-09 10:32:59', b'0', NULL, NULL, '1347732307880730624', '<p>每个商家有不同的结算周期。</p><p>商家按照不同的结算周期生成结算单。</p><p>商家对账完结算单后此结算单可进行结算。</p><p>平台按照商家入驻时填写的银行进行进行线下结算。</p>', 1, '如何与商家结算？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1364720226167422976, 'admin', '2021-02-24 23:33:52', b'0', 'admin', '2021-11-25 23:08:38', '1369921726825103362', '一个商品同一时间段只能设置 1 个满额活动，不同时段可以设置不同的满额活动。', 20, '一个商品可以设置几个满额活动&#xff1f;', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1364722349428965376, 'admin', '2021-02-24 23:42:18', b'0', 'admin', '2021-12-02 11:49:47', '1347450302295203840', '促销活动：分为单品促销、店铺促销、优惠券。<img /><img src=\"https://lilishop-oss.oss-cn-beijing.aliyuncs.com/9da42062f4414443947f4d40c70bb7ed.jpg\" />', 22, '促销计算规则', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1369921919213633536, 'admin', '2021-03-11 02:03:32', b'0', 'admin', '2021-09-09 16:11:49', '1369921726825103360', '<p><span style=\"font-size: 1em;\">一个商品同一时间段只能设置 1 个满额活动，不同时段可以设置不同的满额活动。</span><br></p>', 1, '一个商品可以设置几个满额活动？', 'OTHER', b'0');
INSERT INTO `li_article` VALUES (1369922025446965248, 'admin', '2021-03-11 02:03:57', b'0', 'admin', '2021-09-09 16:11:47', '1369921726825103360', '<p>公告公告公告，嘿嘿嘿~~~~</p><p>一个秒杀活动只能参与一次，不能重复提交参加。</p>', 2, '一个秒杀活动能参与多次吗？', 'OTHER', b'0');
INSERT INTO `li_article` VALUES (1369922111602163712, 'admin', '2021-03-11 02:04:18', b'0', 'admin', '2021-10-22 19:33:23', '1369921726825103360', '<p><span style=\"font-size: 1em;\">订单金额为：周期内的付款订单。</span><br></p><p><br>退款金额为：周期内的退款金额。<br><br>佣金金额为：周期内订单平台收取的佣金。<br><br>商品分销金额：周期内订单产生的分销佣金。<br><br>平台优惠券金额：周期内订单使用的平台优惠券平台承担部分的金额。<br><br>退还佣金：退款订单平台收取的佣金。<br><br>退还平台优惠券：退款订单商家收取的平台优惠券金额。<br><br><br><br>结算金额=订单金额-平台分佣-退单金额-商品分销费用-退还平台优惠券+退还佣金+平台优惠券+积分抵现金额。</p>', 3, '店铺与平台的结算规则', 'OTHER', b'0');
INSERT INTO `li_article` VALUES (1370177884043345920, 'admin', '2021-03-11 19:00:39', b'0', 'admin', '2021-09-09 16:11:48', '1369921726825103360', '<p><span style=\"font-size: 1em;\">多人拼团有虚拟成团的功能。</span><br></p><p>在新建多人拼团活动的时候，如果想要提高成团率，可以展开高级设置，勾选模拟成团。如果不希望买家虚拟成团，则可以不勾选虚拟成团。<br>开启模拟成团后，满足条件的团，系统将会模拟“匿名买家”凑满该团，仅需对真实拼团买家发货。建议合理开启，以提高成团率。</p>', 1, '多人拼团有虚拟成团的功能吗？', 'OTHER', b'0');
INSERT INTO `li_article` VALUES (1370178083092430848, 'admin', '2021-03-11 19:01:26', b'0', NULL, NULL, '', '<p><span style=\"font-size: 1em;\">商品编辑里面的规格名、规格值历史记录目前不支持删除。</span><br></p>', 1, '商品编辑里面的规格名、规格值历史记录可以删除吗？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1370178171978121216, 'admin', '2021-03-11 19:01:48', b'0', NULL, NULL, '', '<p>已成团订单其中1笔申请退款，按正常订单处理，这个团的其他订单不受影响，还是可以正常发货的。</p>', 1, '已成团订单，其中有一人申请退款，对同团其他订单有影响吗？', 'OTHER', b'1');
INSERT INTO `li_article` VALUES (1370178254094204928, 'admin', '2021-03-11 19:02:07', b'0', 'admin', '2021-09-09 16:11:51', '1369921726825103360', '<p>优惠券不能用来抵扣订单中的运费。</p>', 1, '优惠券可以抵扣运费吗？', 'OTHER', b'0');
INSERT INTO `li_article` VALUES (1371779927900160000, 'admin', '2021-03-16 06:06:36', b'0', 'admin', '2021-11-04 19:10:47', '1371779742369316864', '<p>APP隐私协议<br />\n以下隐私协议是xxx公司（以下简称\"我们\"） 对用户隐私保护的许诺，请您务必仔细阅读，以了解我们关于管理您个人信息的情况。本隐私协议使用协议\"的重要组成部分，与其具有同等法律效力。</p>', 1, '隐私策略', 'PRIVACY_POLICY', b'1');
INSERT INTO `li_article` VALUES (1371780016521609216, 'admin', '2021-03-16 06:06:57', b'0', 'admin', '2021-11-04 19:28:07', '1371779742369316864', '<p>关于，关于我们</p><p><img src=\"https://lilishop-oss.oss-cn-beijing.aliyuncs.com/b280f3d1b3504cbeb0a8dc0fab3a24ba.png\" /></p>', 1, '关于我们', 'ABOUT', b'1');
INSERT INTO `li_article` VALUES (1371992635077558272, 'admin', '2021-03-16 20:11:49', b'0', 'admin', '2021-11-04 19:28:07', '1371779742369316864', '<p>证照</p>', 1, '证照信息', 'LICENSE_INFORMATION', b'1');
INSERT INTO `li_article` VALUES (1371992704333905920, 'admin', '2021-03-16 20:12:06', b'0', 'admin', '2021-11-04 19:28:05', '1371779742369316864', '<p>用户注册及使用APP隐私协议<br />\n<br />\n在此特别提醒您（用户）在注册成为用户之前，请认真阅读本《用户协议》（以下简称“协议”），确保您充分理解本协议中各条款。请您审慎阅读并选择接受或不接受本协议。您的注册、登录、使用等行为将视为对本协议的接受，并同意接受本协议各项条款的约束。</p>', 1, '用户协议', 'USER_AGREEMENT', b'1');
INSERT INTO `li_article` VALUES (1394449958765068288, 'admin', '2021-05-18 08:29:12', b'0', 'admin', '2021-09-09 16:12:03', '1394449540941086720', '<p>1.加载“统一社会信用代码”的营业执照（根据2014年10月1日生效的《企业经营异常名录管理暂行办法》，需确保未在企业经营异常名录中且所售商品属于经营范围内）；</p><p>2.一般纳税人资格证复印件（选择FBP模式或“家电”类目商家必须提供，其他模式尽量提供）；</p><p>3.银行开户许可证复印件；（须有中国人民银行盖章，法人代表与营业执照一致，不一致请提供工商局出具的变更证明；）</p><p>4.法定代表人身份证正反面复印件。</p>', 1, '店铺入驻协议', 'STORE_REGISTER', b'0');
