INSERT INTO `li_goods` VALUES (1415849951439998977, '13011111111', '2021-07-16 09:45:08.300000', b'0', 'admin', '2021-07-20 21:38:05.899000', NULL, '0', 0, '1414475616154390529,1414475720143769601,1414475855422656514', 0, 15.00, 'LEIHON李红国际夏季商场同款假两件五分袖复古碎花印花网纱连衣裙', '份', NULL, 100.00, '<p>一是对前后数据的对比中。如今年的收入与去年同期收入的对比，今年实现的利润与去年的利润对比等等。如通过仪表盘可以清晰的反映出，今年的收入与去年相比，完成了多少。在期末的时候，还可以清晰的反映出，今年收入与上一年收入的对比情况等等。为此仪表盘的一个重要应用，就在于数据之间的对比。</p><p>二是在目标考核中，也有不小的用处。在实际工作中，为了对员工进行<a target=\"_blank\" href=\"https://baike.baidu.com/item/%E7%BB%A9%E6%95%88%E8%80%83%E6%A0%B8/2172522\">绩效考核</a>，往往会为用户设置不同的目标。如会为销售员设置销售目标等等。在这种情况下，就可以仪表盘来直观的反映出销售人员的实际业绩与目标之间的关系。</p>', 'PASS', 'UPPER', '<p>一是对前后数据的对比中。如今年的收入与去年同期收入的对比，今年实现的利润与去年的利润对比等等。如通过仪表盘可以清晰的反映出，今年的收入与去年相比，完成了多少。在期末的时候，还可以清晰的反映出，今年收入与上一年收入的对比情况等等。为此仪表盘的一个重要应用，就在于数据之间的对比。</p><p>二是在目标考核中，也有不小的用处。在实际工作中，为了对员工进行<a target=\"_blank\" href=\"https://baike.baidu.com/item/%E7%BB%A9%E6%95%88%E8%80%83%E6%A0%B8/2172522\">绩效考核</a>，往往会为用户设置不同的目标。如会为销售员设置销售目标等等。在这种情况下，就可以仪表盘来直观的反映出销售人员的实际业绩与目标之间的关系。</p><ol><li>我要吃火锅</li><li>我爱大西瓜<img class=\"eleImg\" data-emoji=\"[doge]\" src=\"http://img.t.sinajs.cn/t4/appstyle/expression/ext/normal/a1/2018new_doge02_org.png\" alt=\"[[doge]]\"/></li></ol><ul class=\"w-e-todo\"><li><span contenteditable=\"false\"><input type=\"checkbox\" checked=\"\"/></span>我们做了</li></ul><ul class=\"w-e-todo\"><li><span contenteditable=\"false\"><input type=\"checkbox\"/></span>明天你们做了</li></ul>', 'https://lilishop-oss.oss-cn-beijing.aliyuncs.com/08aaa8a628564fb28f83d36e49af13aa.JPG', 12.00, 1, b'1', 'RETAIL', b'0', '1376433565247471616', '生活百货', 'dashboard是商业智能仪表盘（business intelligence dashboard，BI dashboard）的简称，它是一般商业智能都拥有的实现数据可视化的模块，是向企业展示度量信息和关键业务指标（KPI）现状的数据虚拟化工具。', NULL, 'https://lilishop-oss.oss-cn-beijing.aliyuncs.com/08aaa8a628564fb28f83d36e49af13aa.JPG?x-oss-process=style/200X200', '200001', '0', 'https://lilishop-oss.oss-cn-beijing.aliyuncs.com/08aaa8a628564fb28f83d36e49af13aa.JPG?x-oss-process=style/400X400', NULL, NULL, NULL, NULL, '[]', 'VIRTUAL_GOODS');
